"""Counterbalanced same-machine A/B/C and staged actual-production attribution.

Original counts, ring capacities, deadlines and integrity checks are unchanged.
All timing remains outside the native loops. Windows thread CPU time is coarse;
wall time and cycle measurements are reported separately, never as game FPS.
"""
import itertools
import json
import os
import platform
import statistics
import subprocess
import uuid
from pathlib import Path
ROOT = Path(__file__).resolve().parents[1]
OUTPUT = ROOT / '.deps/ipc-performance-results'
OUTPUT.mkdir(exist_ok=True)
rows = []


def sample(phase, arch, variant, mode, size, count, capacity, iteration):
    executable_variant = 'C' if variant == 'Q' else variant
    layout = 'known' if variant == 'C' else 'generic'
    directory = ROOT / f'.deps/ipc-perf-{executable_variant}'
    suffix = '-separate' if phase == 'separate-caller' else ''
    args = [str(uuid.uuid4()), str(count), str(size), mode, str(capacity), layout]
    host = subprocess.Popen([str(directory / f'perf-host{arch}{suffix}.exe'), *args],
                            stdout=subprocess.PIPE, stderr=subprocess.STDOUT, text=True)
    client = subprocess.Popen([str(directory / f'perf-client32{suffix}.exe'), *args],
                              stdout=subprocess.PIPE, stderr=subprocess.STDOUT, text=True)
    row = dict(phase=phase, host_arch=arch, variant=variant, layout=layout,
               mode=mode, bytes=size, count=count, capacity=capacity,
               iteration=iteration, valid=False)
    logs = []
    try:
        for process in (client, host):
            logs.append(process.communicate(timeout=8 if mode in ('wrap', 'slow') else 25)[0])
        for process, log in zip((client, host), logs):
            if process.returncode:
                raise RuntimeError(f'exit={process.returncode} {log}')
        metrics = [json.loads(line) for log in logs for line in log.splitlines()
                   if line.startswith('{')]
        if len(metrics) != 2 or {m['role'] for m in metrics} != {'client', 'host'}:
            raise RuntimeError(f'missing measurements {logs}')
        row.update(valid=True, metrics=metrics)
    except (subprocess.TimeoutExpired, RuntimeError) as error:
        row.update(error=str(error), logs=logs)
    finally:
        for process in (client, host):
            if process.poll() is None:
                process.kill()
                process.wait()
    rows.append(row)
    (OUTPUT / 'raw.json').write_text(json.dumps(dict(
        machine=platform.platform(), processor=platform.processor(),
        cpu_count=os.cpu_count(), samples=rows), indent=2))
    print(f'IPC_PERF_SAMPLE {phase} host{arch} {variant} {mode} {size} '
          f'iteration={iteration} valid={row["valid"]}', flush=True)
    if not row['valid'] and variant != 'A':
        raise RuntimeError(f'Checked transport native failure: {row}')


def summarize():
    summary = []
    keys = sorted({(r['phase'], r['host_arch'], r['mode'], r['bytes']) for r in rows})
    for phase, arch, mode, size in keys:
        samples = [r for r in rows if (r['phase'], r['host_arch'], r['mode'], r['bytes'])
                   == (phase, arch, mode, size) and r['iteration'] >= 0]
        variants = ('B', 'F', 'R', 'Q', 'C') if phase == 'attribution' else ('A', 'B', 'C')
        group = dict(phase=phase, host_arch=arch, mode=mode, bytes=size, variants={}, paired={})
        for variant in variants:
            valid = [r for r in samples if r['variant'] == variant and r['valid']]
            stats = dict(passed=len(valid), failed=sum(r['variant'] == variant and not r['valid']
                                                     for r in samples))
            for role in ('client', 'host'):
                for metric in ('wall_ns_call', 'cpu_ns_call', 'end_to_end_ns_call', 'cycles_call'):
                    values = [next(m for m in r['metrics'] if m['role'] == role)[metric] for r in valid]
                    if values:
                        stats[f'{role}_{metric}'] = dict(median=statistics.median(values),
                                                        min=min(values), max=max(values))
            group['variants'][variant] = stats
        pairs = list(zip(variants, variants[1:])) if phase == 'attribution' else [('A', 'B'), ('A', 'C'), ('B', 'C')]
        for old, new in pairs:
            changes = {}
            for role in ('client', 'host'):
                for metric in ('wall_ns_call', 'end_to_end_ns_call', 'cycles_call'):
                    deltas, absolute = [], []
                    for iteration in sorted({r['iteration'] for r in samples}):
                        pair = [r for r in samples if r['iteration'] == iteration and r['valid']]
                        a = next((r for r in pair if r['variant'] == old), None)
                        b = next((r for r in pair if r['variant'] == new), None)
                        if a and b:
                            av = next(m for m in a['metrics'] if m['role'] == role)[metric]
                            bv = next(m for m in b['metrics'] if m['role'] == role)[metric]
                            if av:
                                deltas.append((bv / av - 1) * 100)
                                absolute.append(bv - av)
                    if deltas:
                        changes[f'{role}_{metric}'] = dict(paired_delta_percent_median=statistics.median(deltas),
                            min=min(deltas), max=max(deltas), pairs=len(deltas),
                            paired_absolute_delta_median=statistics.median(absolute))
            group['paired'][f'{old}_to_{new}'] = changes
        summary.append(group)
    (OUTPUT / 'summary.json').write_text(json.dumps(summary, indent=2))
    print('IPC_PERF_SUMMARY ' + json.dumps(summary), flush=True)


# Ring capacity is in DWORDs, exactly as in the pre-optimization comparison.
SCENARIOS = [('batch', 0, 24000, 8388608), ('batch', 64, 24000, 8388608),
             ('batch', 1024, 12000, 8388608), ('batch', 4096, 3000, 8388608),
             ('batch', 65536, 190, 8388608), ('stream', 64, 24000, 8388608),
             ('near-full', 64, 204, 4096), ('wrap', 64, 12000, 4096),
             ('slow', 64, 12000, 4096), ('idle', 0, 1, 4096)]
for arch in ('32', '64'):
    for mode, size, count, capacity in SCENARIOS:
        for variant in ('A', 'B', 'C'):
            sample('comparison', arch, variant, mode, size, count, capacity, -1)
        orders = list(itertools.permutations(('A', 'B', 'C')))
        for iteration in range(11):
            for variant in orders[iteration % len(orders)]:
                sample('comparison', arch, variant, mode, size, count, capacity, iteration)
    for mode, size, count, capacity in (SCENARIOS[0], SCENARIOS[1], SCENARIOS[5]):
        variants = ('B', 'F', 'R', 'Q', 'C')
        for variant in variants:
            sample('attribution', arch, variant, mode, size, count, capacity, -1)
        for iteration in range(7):
            ordered = variants[iteration % 5:] + variants[:iteration % 5]
            if iteration % 2:
                ordered = ordered[::-1]
            for variant in ordered:
                sample('attribution', arch, variant, mode, size, count, capacity, iteration)
    for mode, size, count, capacity in SCENARIOS[:8]:
        for variant in ('A', 'B', 'C'):
            sample('separate-caller', arch, variant, mode, size, count, capacity, -1)
        orders = list(itertools.permutations(('A', 'B', 'C')))
        for iteration in range(11):
            for variant in orders[iteration % len(orders)]:
                sample('separate-caller', arch, variant, mode, size, count, capacity, iteration)
# A failure is retained as failure evidence; it never enters a timing ratio.
summarize()
